/** Free spots per size, in a deque. Claiming is O(1); so is releasing. */
final class Level {
    private final int floor;
    private final Map<SpotSize, Deque<Spot>> free = new EnumMap<>(SpotSize.class);

    Optional<Spot> claim(SpotSize size) {
        Deque<Spot> pool = free.get(size);
        if (pool == null || pool.isEmpty()) return Optional.empty();
        Spot spot = pool.pop();          // O(1)
        spot.occupy();
        return Optional.of(spot);
    }

    void release(Spot spot) {
        spot.vacate();
        free.get(spot.size()).push(spot);   // O(1)
    }

    int freeCount(SpotSize size) {
        return free.getOrDefault(size, new ArrayDeque<>()).size();   // O(1)
    }
}

/** Smallest spot that fits, lowest floor first — the policy most lots use.
 *  Swap this class, and the lot behaves completely differently. */
final class NearestFirstAllocator implements SpotAllocator {
    @Override
    public Optional<Spot> allocate(List<Level> levels, Vehicle vehicle) {
        for (Level level : levels) {                     // levels are floor-ordered
            for (SpotSize size : SpotSize.fittingFrom(vehicle.required())) {
                Optional<Spot> spot = level.claim(size); // smallest fit first
                if (spot.isPresent()) return spot;
            }
        }
        return Optional.empty();
    }
}

interface FeeStrategy {
    Money price(Ticket ticket, Instant exitedAt);
}

/** Hourly, rounded up, with a free grace period. One of many; the point is
 *  that the lot does not know which one it is holding. */
final class HourlyFee implements FeeStrategy {
    private final Map<SpotSize, Money> perHour;
    private final Duration grace;

    @Override
    public Money price(Ticket ticket, Instant exitedAt) {
        Duration stay = Duration.between(ticket.enteredAt(), exitedAt);
        if (stay.compareTo(grace) <= 0) return Money.ZERO;
        long hours = (stay.toMinutes() + 59) / 60;          // round up
        return perHour.get(ticket.spot().size()).times(hours);
    }
}

// The check and the take must be one atomic step. Deque.poll() returns null
// on empty rather than throwing, so there is no separate emptiness check to
// race against — the pop IS the check.
Optional<Spot> claim(SpotSize size) {
    Deque<Spot> pool = free.get(size);
    if (pool == null) return Optional.empty();
    Spot spot = pool.poll();               // ConcurrentLinkedDeque: atomic
    if (spot == null) return Optional.empty();
    spot.occupy();
    return Optional.of(spot);
}
